import React, { useState, useEffect, useRef, useCallback } from "react";
import { Modal } from "react-bootstrap";
// import { resendOtpslogin } from "../../../../api/login/Login";
import { sinupApi } from "../../../../api/login/Login";
import {
  toastErrorMessage,
  toastSuccessMessage,
} from "../../../compeleteRegister/ToastShare";

const MobilesinupOtpModal = ({
  show,
  onHide,
  otp,
  inputs,
  otpMessage,
  otpError,
  handleResendOTP,
  otpHandleChange,
  handleKeyDown,
  handleOtpSubmit,
  setOtp,
  // resendOtpslogin, // Assuming you have an API function for resending OTP
  storedMobileNo,
  logintoken,
  setLoginToken,
}) => {
  const [isTimerEnded, setIsTimerEnded] = useState(false);
  const [timeLeft, setTimeLeft] = useState(120);
  const [resendLoading, setResendLoading] = useState(false);
  const [isResendDisabled, setIsResendDisabled] = useState(true);

  const timerRef = useRef(null);

  const formatTime = (seconds) => {
    const minutes = Math.floor(seconds / 60);
    const remainingSeconds = seconds % 60;
    return `${minutes.toString().padStart(2, "0")}:${remainingSeconds
      .toString()
      .padStart(2, "0")}`;
  };

  const startTimer = useCallback(() => {
    if (timerRef.current) clearInterval(timerRef.current);

    setTimeLeft(120);
    setIsTimerEnded(false);
    setIsResendDisabled(true);

    timerRef.current = setInterval(() => {
      setTimeLeft((prevTime) => {
        if (prevTime <= 1) {
          clearInterval(timerRef.current);
          setIsResendDisabled(false);
          setIsTimerEnded(true);
          return 0;
        }
        return prevTime - 1;
      });
    }, 1000);
  }, []);

  useEffect(() => {
    if (!show) return;
    startTimer();
    return () => {
      if (timerRef.current) clearInterval(timerRef.current);
    };
  }, [show, startTimer]);

  useEffect(() => {
    if (show) {
      setTimeout(() => {
        if (inputs.current && inputs.current[0]) {
          inputs.current[0].focus();
        }
      }, 300);
    }
  }, [show]);

  const handleResendOtp = useCallback(async () => {
    try {
      setResendLoading(true);
      setIsResendDisabled(true);

      const response = await sinupApi({
        mobileNo: storedMobileNo,
        emailId: "",
      });

      if (!response?.data?.error) {
        toastSuccessMessage(response?.data?.message || "OTP resent to your WhatsApp number successfully");
        const newToken = response?.data?.data?.user;
        if (newToken && setLoginToken) {
          setLoginToken(newToken);
          // console.log("New OTP token:", newToken);
        }

        setOtp(new Array(6).fill(""));
        startTimer();

        setTimeout(() => {
          if (inputs.current && inputs.current[0]) {
            inputs.current[0].focus();
          }
        }, 300);
      } else {
        toastErrorMessage(response?.data?.message);
      }
    } catch (error) {
      toastErrorMessage("Something went wrong. Please try again.");
    } finally {
      setResendLoading(false);
    }
  }, [startTimer, setOtp, storedMobileNo, setLoginToken]);

  // const handleResendOtp = useCallback(async () => {
  //   try {
  //     setResendLoading(true);
  //     setIsResendDisabled(true);
  //     const response = await resendOtpslogin({
  //       customer_mobile: storedMobileNo,
  //       user_id: logintoken,
  //     });
  //     // console.log("response", response);
  //     if (response?.data?.statusCode == 200) {
  //       toastSuccessMessage(response?.data?.message);
  //       setOtp(new Array(6).fill(""));
  //       startTimer();
  //       setTimeout(() => {
  //       if (inputs.current && inputs.current[0]) {
  //         inputs.current[0].focus();
  //       }
  //     }, 300);
  //     } else {
  //       toastErrorMessage(response?.data?.data?.message);
  //     }
  //   } catch (error) {
  //     console.error("Error resending OTP:", error);
  //   } finally {
  //     setResendLoading(false);
  //   }
  // }, [startTimer, setOtp, resendOtpslogin, storedMobileNo, logintoken]);

  const localKeyDown = (index, e) => {
    if (e.key === "Enter" && otp.every((val) => val !== "")) {
      handleOtpSubmit("mobile");
    } else {
      handleKeyDown(index, e, inputs);
    }
  };

  return (
    <Modal
      show={show}
      onHide={onHide}
      centered
      backdrop="static"
      keyboard={false}
      className="email-optp-modle"
      style={{ zIndex: 1050 }}
    >
      <Modal.Body
        style={{
          backgroundColor: `var(--bs-primary1)`,
          color: `var(--bs-primary2)`,
          border: "2px solid var(--bs-primary3)",
          transform: "translateZ(0)",
        }}
      >
        <button
          onClick={onHide}
          className="otp-close-btn"
          style={{
            position: "absolute",
            top: "10px",
            right: "10px",
            background: "transparent",
            border: "none",
            fontSize: "22px",
            color: "#fff",
            cursor: "pointer",
            zIndex: 2000,
          }}
        >
          ✕
        </button>
        <div className="set-head">
          <div className="row">
            <div className="col-lg-12">
              <div className="headinf-otp">
                <h2>WhatsApp OTP Verification</h2>
                <p className="set-lage">
                  Enter the 6-digit verification code sent to your WhatsApp number.
                </p>
              </div>
              <div className="verification-code">
                <p>Verify OTP</p>
                <div className="resend-otp">
                  <span
                    className="resend-otp"
                    onClick={handleResendOtp}
                    style={{
                      cursor: isResendDisabled ? "default" : "pointer",
                      color: isResendDisabled ? "gray" : "gray",
                      pointerEvents: isResendDisabled ? "none" : "auto",
                    }}
                  >
                    {!isResendDisabled
                      ? "Resend OTP"
                      : `Resend in ${formatTime(timeLeft)}`}
                  </span>
                </div>
              </div>
              {/* OTP input section */}
              <div className="col-lg-12">
                <div className="otp-inputs">
                  {otp.map((value, index) => (
                    <input
                      key={index}
                      type="text"
                      inputMode="numeric"
                      pattern="[0-9]*"
                      maxLength="1"
                      value={value}
                      className="otp-input otp-input-login"
                      onChange={(e) =>
                        otpHandleChange(index, e.target.value, setOtp, inputs)
                      }
                      onKeyDown={(e) => localKeyDown(index, e)}
                      ref={(input) => (inputs.current[index] = input)}
                      onKeyPress={(e) => {
                        if (!/[0-9]/.test(e.key)) {
                          e.preventDefault();
                        }
                      }}
                      onPaste={(e) => e.preventDefault()}
                    />
                  ))}
                </div>
              </div>
              <div className="col-lg-12">
                <div className="input-group">
                  <button
                    type="button"
                    disabled={otp.some((digit) => digit === "") || resendLoading}
                    className={`form-control mt-2 ${
                      otp.some((digit) => digit === "") || resendLoading
                        ? "disableebuttoncls not-allowed"
                        : "btn-login"
                    }`}
                    onClick={() => handleOtpSubmit("mobile")}
                  >
                    {resendLoading ? "Submitting..." : "Submit OTP"}
                  </button>
                </div>
              </div>
              {otpMessage && (
                <div className="alert alert-success mt-3">{otpMessage}</div>
              )}
              {otpError && (
                <div className="alert alert-danger mt-3">{otpError}</div>
              )}
            </div>
          </div>
        </div>
      </Modal.Body>
    </Modal>
  );
};

export default MobilesinupOtpModal;
